"use client";
// vendored from @patternmode/scrollframe@2.0.9 — generated by scripts/build-registry.mjs; do not hand-edit.

import { useRender } from "@base-ui/react/use-render";
import { joinClassNames } from "@/lib/patternmode/system";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useLayoutEffect, useRef } from "react";
import type { MouseEvent } from "react";

import { useScrollFrame } from "./scroll-frame-context";
import type {
  ScrollFrameEdge,
  ScrollFrameEdgeState,
  ScrollFrameMovementControlProps,
} from "./scroll-frame-types";
import { defaultControlAxis } from "./scroll-frame-utils";

const isMovementBlocked = (
  axisState: ScrollFrameEdgeState[keyof ScrollFrameEdgeState],
  direction: ScrollFrameEdge,
) => !axisState.scrollable || (direction === "start" ? axisState.atStart : axisState.atEnd);

const getControlLabel = (label: string | undefined, direction: ScrollFrameEdge) =>
  label ?? (direction === "start" ? "Scroll backward" : "Scroll forward");

const getControlIcon = (direction: ScrollFrameEdge) =>
  direction === "start" ? (
    <ChevronLeft aria-hidden="true" size={16} strokeWidth={2} />
  ) : (
    <ChevronRight aria-hidden="true" size={16} strokeWidth={2} />
  );

/* Focus is lost when the control left the document or was disabled while it
   held focus. A control still attached and enabled keeps its focus. */
const isFocusLost = (control: HTMLElement) => {
  if (control.isConnected && !control.matches(":disabled")) {
    return false;
  }
  const active = control.ownerDocument.activeElement;
  return active === null || active === control || active === control.ownerDocument.body;
};

/*
 * A control that reaches its edge hides (`auto`) or disables (`disabled`). If
 * it held focus, the browser drops focus to <body> and a keyboard user is
 * thrown back to the top of the page. Hand focus to the frame's other enabled
 * control, else its viewport. Deferred to a microtask so the opposite control,
 * which may mount in the same commit, exists by then.
 */
const handOffFocus = (control: HTMLElement) => {
  const root = control.closest<HTMLElement>('[data-slot="scrollframe"]');
  if (!root) {
    return;
  }
  queueMicrotask(() => {
    if (!(root.isConnected && isFocusLost(control))) {
      return;
    }
    const target =
      [...root.querySelectorAll<HTMLElement>('[data-slot="scrollframe-control"]')].find(
        (candidate) =>
          candidate !== control &&
          !candidate.matches(':disabled, [aria-disabled="true"]') &&
          candidate.closest('[data-slot="scrollframe"]') === root,
      ) ?? root.querySelector<HTMLElement>('[data-slot="scrollframe-viewport"]');
    target?.focus({ preventScroll: true });
  });
};

const ScrollFrameMovementControl = ({
  render,
  axis,
  children,
  className,
  direction,
  disabled,
  onClick,
  type,
  visibility,
  ...props
}: ScrollFrameMovementControlProps & { direction: ScrollFrameEdge }) => {
  const { axes, controlVisibility, edgeState, scrollByStep } = useScrollFrame();
  const isRendered = render !== undefined;
  const resolvedAxis = axis ?? defaultControlAxis(axes);
  const resolvedVisibility = visibility ?? controlVisibility;
  const axisState = edgeState[resolvedAxis];
  const movementBlocked = isMovementBlocked(axisState, direction);
  const hidden =
    resolvedVisibility === "hidden" || (resolvedVisibility === "auto" && movementBlocked);
  const controlDisabled = disabled === true || movementBlocked;
  const label = getControlLabel(props["aria-label"], direction);
  const nodeRef = useRef<HTMLElement | null>(null);

  // Hidden: the node is detached while focused. React runs this cleanup
  // before removing the node, so it can still see that it holds focus. The
  // callback is new each render, so the cleanup also runs on re-renders that
  // keep the node; `handOffFocus` ignores those because the control is still
  // attached and enabled.
  const attachRef = (node: HTMLElement | null) => {
    nodeRef.current = node;
    return () => {
      nodeRef.current = null;
      if (node !== null && node.ownerDocument.activeElement === node) {
        handOffFocus(node);
      }
    };
  };

  // Disabled: a natively disabled button loses focus. A rendered control uses
  // aria-disabled instead and keeps it, so it needs no hand-off.
  const nativelyDisabled = !isRendered && controlDisabled;
  useLayoutEffect(() => {
    const node = nodeRef.current;
    if (nativelyDisabled && node && node.ownerDocument.activeElement === node) {
      handOffFocus(node);
    }
  }, [nativelyDisabled]);

  // `useRender` must run unconditionally, so build the element before the
  // early return and gate rendering on `hidden` afterwards.
  const element = useRender({
    defaultTagName: "button",
    props: {
      ...props,
      "aria-disabled": isRendered && controlDisabled ? true : props["aria-disabled"],
      "aria-label": label,
      children: children ?? getControlIcon(direction),
      className: joinClassNames("patternmode-scrollframe__control", className),
      "data-axis": resolvedAxis,
      "data-direction": direction,
      "data-slot": "scrollframe-control",
      disabled: isRendered ? undefined : controlDisabled,
      onClick: (event: MouseEvent<HTMLButtonElement>) => {
        onClick?.(event);
        if (!event.defaultPrevented && !controlDisabled) {
          scrollByStep(direction, resolvedAxis);
        }
      },
      type: isRendered ? undefined : (type ?? "button"),
    },
    ref: attachRef,
    render,
  });

  if (hidden) {
    return null;
  }

  return element;
};

export const ScrollFramePrevious = (props: ScrollFrameMovementControlProps) => (
  <ScrollFrameMovementControl {...props} direction="start" />
);

export const ScrollFrameNext = (props: ScrollFrameMovementControlProps) => (
  <ScrollFrameMovementControl {...props} direction="end" />
);
